import React from 'react'
import heroImage from '../aset/profil.jpg'
import { TypeAnimation } from 'react-type-animation'

const Hero = () => {
  return (
    <div className='grid grid-cols-1 sm:grid-cols-3 gap-8 max-w-[1200px] md:h-[70vh] mx-auto py-8'>
        
      <div className='col-span-1 my-auto mx-auto w-[300px] h-auto lg:w-[480px]'>
        
      </div>

      <div className='col-span-2 px-5 my-auto'>
        
        <h1 className="text-white text-4xl sm:text-4xl  lg:text-6xl font-extrabold">
            <span className="primary-color">
                I'm a
            </span> <br/>
            <TypeAnimation
            sequence={[
                'Web Developer',
                1000,
                'Artificial Intelligence Enthusiast',
                1000,
                'Software Engineer',
                1000,
            ]}
            wrapper="span"
            speed={50}
            repeat={Infinity}
            />
        </h1>
        
        <p className="text-white sm:text-lg my-6">
          {
        <div className="my-8">
            
            <a href="https://drive.google.com/file/d/1IK-LixELmvTtiaPBb32CJ8r4ja6Wgkk7/view?usp=drive_link" className="px-6 py-3 w-full border border-gray-400 rounded-xl max-w-[200px] text-white hover:border-white/50 
            bg-gradient-to-b from-purple-950/0 to-purple-950/30 hover:from-pink-900/40 hover:to-pink-800/40 inset-glow">
              My Resume
            </a>
        </div>
        }
        
        </p>
       
      </div>

    </div>
  )
}

export default Hero
