import React, { useState } from 'react'
import project1 from '../aset/herokost.png'
import project2 from '../aset/ai_resume.png'
import project3 from '../aset/project3.jpeg'
import project4 from '../aset/cctv_motion.png'
import project5 from '../aset/mbti.jpg'
import project6 from '../aset/lab.png'
import project7 from '../aset/image.png'
import project8 from '../aset/hp.png'

const Work = () => {
  const [activeCategory, setActiveCategory] = useState('all')

  const projects = [
    {
      id: 1,
      image: project1,
      title: 'Kost-Hero',
      category: 'tech',
      description:
        'A responsive website designed for students to explore, buy, and sell property in a simple way.',
      techStack: ['React.js', 'Tailwind','SQL','PHP'],
      link: '',
    },
    {
      id: 2,
      image: project2,
      title: 'AI Resume Analyzer',
      category: 'tech',
      description:
        'AI-powered resume analysis tool that evaluates candidates based on ATS Framework.',
      techStack: ['Python', 'Puter.js', 'NLP', 'ChatGPT 4.0'],
      link: 'https://ai-resume-check.puter.site',
    },
    {
      id: 3,
      image: project3,
      title: 'Craftify',
      category: 'tech',
      description:
        'E-commerce platform with user authentication and payment integration.',
      techStack: ['React.js', 'Tailwind', 'SQL', 'REST API', 'Laravel', 'PHP'],
      link: '',
    },
    {
      id: 4,
      image: project4,
      title: 'CCTV Motion Analysis System',
      category: 'misc',
      description:
        'Motion analysis system for security monitoring with interactive features.',
      techStack: ['Python', 'OpenCV', 'Streamlit', 'React.js', 'Tailwind'],
      link: 'https://fast-background-for-subtraction-videosurveilans.streamlit.app/',
    },
    {
      id: 5,
      image: project5,
      title: 'Handwriting-based MBTI Classifier',
      category: 'tech',
      description:
        'MBTI personalities classification using handwriting images.',
      techStack: ['Python', 'CNN', 'TensorFlow', 'Computer Vision', 'scikit-learn'],
      link: '',
    },
    {
      id: 6,
      image: project6,
      title: 'STEDLAB',
      category: 'tech',
      description: 'Virtual Laboratory for Science Education.',
      techStack: ['figma', 'UI/UX'],
      link: '',
    },
    {
      id: 7,
      image: project7,
      title: 'Brain Tumor Detection using Machine Learning',
      category: 'tech',
      description:
        'Machine Learning system for detecting brain tumors using MRI images.',
      techStack: ['Python', 'CNN', 'TensorFlow', 'OpenCV', 'Computer Vision'],
      link: 'https://github.com/nia212/Brain-Tumor-CNN-ANO',
    },
    {
      id: 8,
      image: project8,
      title: 'Survival Game Harry Potter Theme',
      category: 'misc',
      description:
        'Game development project using Java programming.',
      techStack: ['Java', 'LibGDX', 'Canva', 'Photoshop'],
      link: '',
    },
  ]

  const categories = [
    { key: 'all', label: 'All' },
    { key: 'tech', label: 'Web & AI Projects' },
    { key: 'pubs', label: 'Publications' },
    { key: 'misc', label: 'Miscellaneous' },
  ]

  const techColors = [
    'bg-cyan-900/50 text-cyan-300 border-cyan-700',
    'bg-emerald-900/50 text-emerald-300 border-emerald-700',
    'bg-indigo-900/50 text-indigo-300 border-indigo-700',
    'bg-pink-900/50 text-pink-300 border-pink-700',
    'bg-orange-900/50 text-orange-300 border-orange-700',
    'bg-purple-900/50 text-purple-300 border-purple-700',
    'bg-yellow-900/50 text-yellow-300 border-yellow-700',
  ]

  const filteredProjects =
    activeCategory === 'all'
      ? projects
      : projects.filter((p) => p.category === activeCategory)

  return (
    <section className="min-h-screen py-16" id="work">
      <div className="max-w-7xl mx-auto px-6">

        {/* TITLE */}
        <div className="text-center mb-16">
          <h2 className="text-4xl md:text-5xl font-bold bg-gradient-to-r primary-color bg-clip-text text-transparent">
            My Projects
          </h2>
        </div>

        {/* FILTER */}
        <div className="flex justify-center mb-12">
          <div className="bg-slate-700/50 backdrop-blur-sm rounded-2xl p-2 border border-slate-600">
            <div className="flex flex-wrap gap-2">
              {categories.map((cat) => (
                <button
                  key={cat.key}
                  onClick={() => setActiveCategory(cat.key)}
                  className={`px-6 py-2 rounded-xl font-semibold transition-all duration-300 ${
                    activeCategory === cat.key
                      ? 'bg-pink-950 text-white scale-105 shadow-lg'
                      : 'text-gray-300 hover:bg-slate-600/50'
                  }`}
                >
                  {cat.label}
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* GRID */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 items-stretch">
          {filteredProjects.map((project) => {
            const Card = (
              <div className="group flex flex-col h-full bg-slate-800/50 backdrop-blur-sm
                              rounded-xl border border-slate-700 overflow-hidden
                              transition-all duration-500 hover:-translate-y-2
                              hover:shadow-2xl">

                {/* IMAGE */}
                <div className="relative h-64 overflow-hidden">
                  <img
                    src={project.image}
                    alt={project.title}
                    className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110"
                  />
                </div>

                {/* CONTENT */}
                <div className="p-6 flex flex-col flex-grow">
                  <h3 className="text-xl font-bold text-gray-100 mb-2">
                    {project.title}
                  </h3>

                  <p className="text-gray-300 text-sm mb-4">
                    {project.description}
                  </p>

                  {/* TECH STACK */}
                  <div className="flex flex-wrap gap-2 mb-4">
                    {project.techStack.map((tech, idx) => (
                      <span
                        key={idx}
                        className={`px-2.5 py-1 text-xs rounded-full border
                                    ${techColors[idx % techColors.length]}`}
                      >
                        {tech}
                      </span>
                    ))}
                  </div>

                  {/* CATEGORY */}
                  <span
                    className="mt-auto w-fit px-3 py-1 rounded-full text-xs font-medium
                               bg-indigo-900/50 text-indigo-300 border border-indigo-700"
                  >
                    {project.category === 'tech' ? 'Web &or AI' : project.category}
                  </span>
                </div>
              </div>
            )

            return project.link ? (
              <a
                key={project.id}
                href={project.link}
                target="_blank"
                rel="noopener noreferrer"
              >
                {Card}
              </a>
            ) : (
              <div key={project.id}>{Card}</div>
              
            )
            
          })}
          {filteredProjects.length === 0 && (
            <div className="col-span-full flex justify-center py-24">
                <h3 className="text-2xl font-bold text-gray-100">
                Coming Soon
                </h3>
            </div>
           )}


        </div>
      </div>
    </section>
  )
}

export default Work
